import {disasterReliefReport} from './disaster-relief.js?v=shaped-details-1';
import {backgroundRulesReport,scenarioAllowsBackground} from './scenario-background-rules.js?v=shaped-details-1';
import {pendingWarnings} from './emergency-session.js?v=shaped-details-1';
import {emergencyLocations} from './emergency-navigation.js?v=shaped-details-1';
import {setRandomUfos} from './ufo.js?v=shaped-details-1';
import {setRandomWhirlpools} from './whirlpool.js?v=shaped-details-1';
import {setRandomToxicClouds,toxicCloudRisk,toxicCloudSource} from './toxic-cloud.js?v=shaped-details-1';
import {setRandomSpaceJunk} from './space-junk.js?v=shaped-details-1';
import {setRandomRiots,unrestRisk} from './riots.js?v=shaped-details-1';
import {setRandomLocusts,locustRisk,cropDusterReport} from './locusts.js?v=shaped-details-1';
import {setRandomFires,setRandomEarthquakes,setRandomTornadoes,soundSiren} from './emergency.js?v=shaped-details-1';
export function showEmergency(ui){const {city,dialog,close,update,save,notify,setTool,setLayer,goToFire,resume,review}=ui,c=city(),e=c.emergency,warning=e.tornado?.warningSteps||e.ufo?.warningSteps,locations=emergencyLocations(c),randomAllowed=scenarioAllowsBackground(c,'randomDisasters'),$=v=>document.querySelector(v);
 dialog('Emergency · disasters & recovery',`<p>${e.ufo?.warningSteps?'An alien craft is approaching. Sound the early warning siren before continuing: residents who trust the warning will take shelter.':e.ufo?'An alien craft is striking surface structures with six beams. Emergency crews cannot stop the attack. Continue until it departs, then clear rubble and reconnect damaged neighborhoods.':e.whirlpool?'A whirlpool is damaging bridges and shoreline structures in four expanding surges. Emergency crews cannot stop the current. Continue the emergency, then rebuild crossings and inspect disconnected neighborhoods.':e.toxicCloud?'A toxic cloud is drifting through the city. Affected homes and businesses empty; roads and utility networks remain. Emergency units cannot stop the gas. Continue the emergency, then restore services so the zones can redevelop.':e.spaceJunk?'Satellite fragments are falling near the selected area. Six impacts arrive over 24 response steps. Firefighters cannot stop impacts; dispatch them to contain the fires. Close this panel to continue.':e.riot?'A riot is in progress. Dispatch police near the moving crowd. Nearby police coverage helps automatically; firefighters must handle any resulting fires. Close this panel to continue.':e.locust?'Locusts are seeking trees and farm crops. Dispatch up to three crop dusters; spray ahead of the swarm or directly onto it. Close this panel to continue the emergency.':e.tornado?.warningSteps>0?'A tornado is approaching. Sound the early warning siren to help residents take shelter, then continue the emergency. This panel holds the warning countdown.':e.tornado?`A tornado of intensity ${e.tornado.intensity} / 100 is crossing the city at ${e.tornado.speed} speed (${e.tornado.age} / ${e.tornado.distance} path tiles affected). Firefighters can fight secondary fires but cannot stop the wind. Close this panel to continue the storm; the calendar waits until the emergency ends.`:e.earthquake?`An earthquake of magnitude ${e.earthquake.magnitude} / 100 is in progress. Firefighters cannot stop the shaking. Close this panel to continue; the calendar waits until the quake and any resulting fires end.`:e.active?'A fire is in progress. Close this panel to respond. Disaster steps run slowly; the calendar and normal speed controls wait until the emergency ends. Panels pause the response clock.':'Prepare water coverage and funded fire stations before an emergency. Start a fire, earthquake or tornado yourself, or allow them to occur randomly. Quakes break roads and utilities as well as buildings.'}</p><div class="actions">${e.active?`${e.riot?'<button id="quickPolice" class="primary">Dispatch police</button>':e.locust?'<button id="quickDuster" class="primary">Dispatch crop dusters</button>':warning&&pendingWarnings(e).length?'<button id="quickSiren" class="primary">Sound early warning siren</button>':''}<button id="resumeFire" class="${e.ufo||e.whirlpool||e.toxicCloud?'primary':''}">Continue emergency</button><button id="dispatchUnit" class="${!e.ufo&&!e.whirlpool&&!e.toxicCloud&&!e.riot&&!e.locust&&!warning?'primary':''}">Dispatch firefighters</button><button id="goFire">Next emergency location</button>`:'<button id="startUfo">Start an alien attack</button><button id="startWhirlpool">Start a whirlpool</button><button id="startToxicCloud">Start a toxic cloud</button><button id="startSpaceJunk">Start falling space junk</button><button id="startRiot">Start a riot</button><button id="startLocust">Start a locust swarm</button><button id="startFire">Start a fire on the map</button><button id="startQuake">Choose earthquake epicenter</button><button id="startTornado">Start a tornado on the map</button>'}<button id="fireMap">Fire coverage</button><button id="fireRisk">Flammability</button><button id="clearRubble">Bulldoze / firebreak</button></div>${e.active?`<details><summary>Add another disaster</summary><p>Different disaster types can overlap in one response session. Existing units stay deployed. One major hazard of each type may be active, alongside multiple fire areas. The calendar waits until all hazards and fires are resolved.</p><div class="actions">${Object.entries({ufo:'Alien attack',whirlpool:'Whirlpool',toxicCloud:'Toxic cloud',spaceJunk:'Falling space junk',riot:'Riot',locust:'Locust swarm',earthquake:'Earthquake',tornado:'Tornado',ignite:'Fire'}).filter(([key])=>!e[key]).map(([key,label])=>`<button data-start-hazard="${key}">Add ${label}</button>`).join('')}</div></details>`:''}<div class="metric-grid emergency-metrics"><div><small>Burning tiles</small><strong>${c.stats.burningTiles}</strong></div><div><small>Firefighter units</small><strong>${e.units.length} / ${c.stats.fireUnits}</strong></div><div><small>Buildings / trees destroyed</small><strong>${e.destroyed}</strong></div><div><small>Residents displaced</small><strong>${e.displaced}</strong></div></div><details ${e.riot?'open':''}><summary>Police response</summary><p>Crime: ${Math.round(c.stats.averageCrime)}/100. Resident wellbeing: ${Math.round(c.stats.aura)}/100. Elevated unrest: ${e.unrestMonths} consecutive months. Outbreak eligibility begins at six months. Current monthly riot chance: ${((randomAllowed?unrestRisk(c):0)*100).toFixed(2)}%.</p><p>${e.riots} riots recorded. ${e.riot?`Crowd anger: ${Math.ceil(e.riot.anger)}%. `:''}Police squads: ${e.policeUnits.length} / ${1+c.tiles.filter(t=>t.type==='police').length}. One volunteer squad is always available. Police funding, strikes and jail capacity affect additional squads. Police cannot extinguish fires.</p>${e.active?'<button id="dispatchPolice">Dispatch police</button>':''}</details><details ${e.locust?'open':''}><summary>Locust response</summary>${e.locust?cropDusterReport(c):''}<p>${e.locust?`Swarm strength: ${e.locust.strength}%. Crop dusters: ${e.cropDusters.length}/3. Spray takes two response steps to arrive and remains for ten steps within four tiles.`:`${e.locustPlagues} plagues recorded; ${e.vegetationLost} trees or farm tiles lost.`} Locusts strip vegetation and clear farm development. Replant trees and let farm zones redevelop after the plague.</p>${e.locust?'<button id="dispatchDuster">Dispatch crop dusters</button>':''}</details><details ${warning?'open':''}><summary>Early warning siren</summary><p>Public trust: ${e.sirenTrust}%. False alarms: ${e.falseAlarms}. ${e.shelter>0?'Residents are sheltering from warned tornadoes or alien attacks.':'Sound the siren during a tornado or alien-attack warning. False alarms reduce future response; a timely warning slowly rebuilds trust.'}</p><ul>${[['Tornado',e.tornado],['Alien attack',e.ufo]].filter(([,hazard])=>hazard).map(([name,hazard])=>`<li>${name}: ${hazard.warned?(hazard.shelter>0?'warning sounded · sheltering':'warning sounded · no shelter response'):hazard.warningSteps>0?'early warning available':'early warning window passed'}</li>`).join('')}</ul><button id="soundSiren" ${e.active&&(!warning||!pendingWarnings(e).length)?'disabled':''}>${warning&&!pendingWarnings(e).length?'Warning sounded':'Sound early warning siren'}</button></details><details><summary>Random disaster settings</summary><label class="ordinance"><input id="randomUfos" type="checkbox" ${e.randomUfos?'checked':''} ${(!randomAllowed||e.active)?'disabled':''}><span>Allow random alien attacks</span></label><p>When the city has occupied zones or constructed facilities, enabling alien attacks permits a 0.2% monthly chance. A warning panel opens before the first strike. Sound the siren before continuing; repeated false alarms reduce protection.</p><label class="ordinance"><input id="randomWhirlpools" type="checkbox" ${e.randomWhirlpools?'checked':''} ${(!randomAllowed||e.active)?'disabled':''}><span>Allow random whirlpools</span></label><p>${c.tiles.some(t=>t.terrain==='water')?'Water is present: enabling whirlpools permits a 0.3% monthly chance. Any water tile can become the center; keep alternate crossings for important routes.':'No surface water: random whirlpools cannot form unless water is added.'}</p><label class="ordinance"><input id="randomToxicClouds" type="checkbox" ${e.randomToxicClouds?'checked':''} ${(!randomAllowed||e.active)?'disabled':''}><span>Allow pollution-driven toxic clouds · ${((randomAllowed?toxicCloudRisk(c):0)*100).toFixed(2)}% monthly chance at current industrial pollution</span></label><p>Cloud risk starts when local air pollution exceeds 50 at an occupied dirty factory or toxic-waste facility. Reduce pollution or transition to clean industry. ${toxicCloudSource(c)?`Highest-risk source: ${toxicCloudSource(c).x+1}, ${toxicCloudSource(c).y+1}.`:'No eligible industrial source.'}</p><label class="ordinance"><input id="randomSpaceJunk" type="checkbox" ${e.randomSpaceJunk?'checked':''} ${(!randomAllowed||e.active)?'disabled':''}><span>Allow random space junk · 0.30% monthly chance</span></label><label class="ordinance"><input id="randomRiots" type="checkbox" ${e.randomRiots?'checked':''} ${(!randomAllowed||e.active)?'disabled':''}><span>Allow unrest-driven riots · risk begins after six months of crime above 40 or wellbeing below 40</span></label><label class="ordinance"><input id="randomLocusts" type="checkbox" ${e.randomLocusts?'checked':''} ${(!randomAllowed||e.active)?'disabled':''}><span>Allow random locust plagues · ${((randomAllowed?locustRisk(c):0)*100).toFixed(2)}% monthly chance at current vegetation and farm count</span></label><label class="ordinance"><input id="randomFires" type="checkbox" ${e.randomFires?'checked':''} ${(!randomAllowed||e.active)?'disabled':''}><span>Allow random fires</span></label><label class="ordinance"><input id="randomQuakes" type="checkbox" ${e.randomEarthquakes?'checked':''} ${(!randomAllowed||e.active)?'disabled':''}><span>Allow random earthquakes</span></label><label class="ordinance"><input id="randomTornadoes" type="checkbox" ${e.randomTornadoes?'checked':''} ${(!randomAllowed||e.active)?'disabled':''}><span>Allow random tornadoes</span></label>${backgroundRulesReport(c)}<p>Random disasters are off initially. You cannot disable a disaster already in progress. Starting a disaster changes this city; save or export a copy first if you want to preserve it.</p></details>${locations.length?`<details open><summary>Active emergency locations (${locations.length})</summary><p>Choose a location, or use Next emergency on the map. Locations follow the order emergencies started. Spreading fires keep their original place. Older imported saves retain their previous order until new emergencies begin.</p><ol>${locations.map(t=>`<li><button data-emergency-location="${t.id}">${t.label} · Tile ${t.x+1}, ${t.y+1}${t.tiles?' · '+t.tiles+' burning tiles':''}</button></li>`).join('')}</ol></details>`:''}<details ${e.ufo?'open':''}><summary>Alien attack recovery</summary><p>${e.ufoAttacks} attacks recorded; ${e.ufoStrikes} beam strikes. There are eight warning steps and six strikes over 24 attack steps. The craft selects developed areas after its first target. Early shelter can spare structures; buried utilities survive. Clear rubble and reconnect roads and power once it leaves.</p></details><details ${e.whirlpool?'open':''}><summary>Whirlpool recovery</summary><p>${e.whirlpools} whirlpools recorded. Connected water within four tiles and its immediate shore are exposed. Buried pipes and subway survive; surface crossings and exposed tunnel portals can be lost. After 24 response steps, rebuild road and rail spans from bank to bank and inspect power and water coverage.</p></details><details ${e.toxicCloud?'open':''}><summary>Toxic cloud recovery</summary><p>${e.toxicClouds} clouds recorded; ${e.toxicEvacuations} developed zone tiles emptied. Wait for the cloud to disperse, inspect utility and road access, and run the city to allow redevelopment. Clouds do not leave rubble or radiation.</p></details><details ${e.spaceJunk?'open':''}><summary>Space junk recovery</summary><p>${e.spaceJunkFalls} debris falls recorded; ${e.spaceJunkImpacts} impacts. ${e.spaceJunk?`${6-Math.floor(e.spaceJunk.age/4)} fragments remain. `:''}Impacts destroy struck surface structures and ignite adjacent buildings. Water impacts cause no damage. Buried pipes and subway survive; exposed tunnel portals may be destroyed.</p></details><details ${e.earthquake||e.tornado?'open':''}><summary>Storm and earthquake recovery</summary><p>${e.quakes} earthquakes and ${e.tornadoes} tornadoes recorded; ${e.infrastructureLost} roads, lines, underground links or tunnels lost. Tornadoes move toward the city center for up to 24 response steps, damaging buildings and surface connections. Buried pipes and subway survive. Each quake spreads damage over eight response steps. Firefighters handle the fires that follow; they cannot prevent quake damage.</p><ol><li>Contain resulting fires and bulldoze rubble.</li><li>Check power and water maps for disconnected neighborhoods.</li><li>Replace broken roads, rail, pipes and subway. A damaged tunnel must be rebuilt between its portals.</li><li>Restore buildings and let cleared zones redevelop.</li></ol><div class="actions"><button id="quakePower">Check power</button><button id="quakeWater">Check pipes</button><button id="quakeSubway">Check subway</button><button id="quakeTunnels">Check tunnels</button></div></details><details ${c.stats.contaminatedTiles>0?'open':''}><summary>Radiation contamination</summary><p>${c.stats.contaminatedTiles} tiles contaminated. Nuclear overload leaves lasting contamination marked ☢ on the map. Residents cannot return there, and construction or landscaping cannot remove it. Relocate affected neighborhoods and facilities.</p></details>${disasterReliefReport(c)}<details ${false?'open':''}><summary>Contain the blaze</summary><ol><li>Choose Dispatch firefighters and click beside the flames. Units arrive immediately.</li><li>You always have one volunteer unit, plus one per fire station. Once all are placed, further clicks move the oldest unit.</li><li>Watered tiles are less flammable. Funded stations respond automatically within their coverage.</li><li>Bulldoze intact buildings around a fire to make a firebreak. Active flames require firefighters.</li><li>After containment, clear rubble and restore services so the existing zones can rebuild.</li></ol></details>${disasterReliefReport(c)}<details ${false?'open':''}><summary>Challenge checkpoint</summary><ul><li>${e.started?'✓ ':''}Respond to a disaster.</li><li>${e.contained?'✓ ':''}Finish an emergency (${e.contained} completed).</li><li>${!c.stats.rubbleTiles&&e.contained?'✓ ':''}Clear the damage and rebuild.</li></ul><p class="fine">Milestone 6 includes fires, earthquakes, tornadoes, locusts, riots, space junk, toxic clouds, whirlpools, alien attacks, reward offers and original challenges from City desk. Disaster rates, damage and timing are approximate. The original scenario catalog remains unfinished. Additional major hazards can be started from this panel; random and scripted event scheduling retain their existing timing. Siren preparation applies to tornadoes and alien attacks.</p><button id="reviewEmergency">Give milestone 6 feedback</button></details>`);
 if($('#quickPolice'))$('#quickPolice').onclick=()=>{resume();setTool('dispatchPolice');close();};
 if($('#quickDuster'))$('#quickDuster').onclick=()=>{resume();setTool('dispatchCropDuster');close();};
 if($('#quickSiren'))$('#quickSiren').onclick=()=>$('#soundSiren').click();
 if(!e.active)$('#startUfo').onclick=()=>{setTool('ufo');close();};
 if(!e.active)$('#startWhirlpool').onclick=()=>{setTool('whirlpool');close();};
 if(!e.active)$('#startToxicCloud').onclick=()=>{setTool('toxicCloud');close();};
 if(!e.active)$('#startSpaceJunk').onclick=()=>{setTool('spaceJunk');close();};
 if(e.active)$('#dispatchPolice').onclick=()=>{resume();setTool('dispatchPolice');close();};else $('#startRiot').onclick=()=>{setTool('riot');close();};
 $('#randomUfos').onchange=()=>{const r=setRandomUfos(c,$('#randomUfos').checked);if(!r.ok)return notify(r.error);save();update();};
 $('#randomWhirlpools').onchange=()=>{const r=setRandomWhirlpools(c,$('#randomWhirlpools').checked);if(!r.ok)return notify(r.error);save();update();};
 $('#randomToxicClouds').onchange=()=>{const r=setRandomToxicClouds(c,$('#randomToxicClouds').checked);if(!r.ok)return notify(r.error);save();update();};
 $('#randomSpaceJunk').onchange=()=>{const r=setRandomSpaceJunk(c,$('#randomSpaceJunk').checked);if(!r.ok)return notify(r.error);save();update();};
 $('#randomRiots').onchange=()=>{const r=setRandomRiots(c,$('#randomRiots').checked);if(!r.ok)return notify(r.error);save();update();showEmergency(ui);};
 $('#randomLocusts').onchange=()=>{const r=setRandomLocusts(c,$('#randomLocusts').checked);if(!r.ok)return notify(r.error);save();update();};
 $('#soundSiren').onclick=()=>{const r=soundSiren(c);if(!r.ok)return notify(r.error);save();update();showEmergency(ui);notify(r.message);};
 document.querySelectorAll('[data-start-hazard]').forEach(b=>b.onclick=()=>{setTool(b.dataset.startHazard);close();});
 document.querySelectorAll('[data-emergency-location]').forEach(b=>b.onclick=()=>{goToFire(b.dataset.emergencyLocation);close();});
 if(e.locust)$('#dispatchDuster').onclick=()=>{resume();setTool('dispatchCropDuster');close();};if(!e.active)$('#startLocust').onclick=()=>{setTool('locust');close();};if(e.active){$('#resumeFire').onclick=()=>{resume();close();};$('#dispatchUnit').onclick=()=>{resume();setTool('dispatchFire');close();};$('#goFire').onclick=()=>{goToFire();close();};}else {$('#startFire').onclick=()=>{setTool('ignite');close();};$('#startTornado').onclick=()=>{setTool('tornado');close();};$('#startQuake').onclick=()=>{setTool('earthquake');close();};}for(const [id,layer] of [['quakePower','power'],['quakeWater','water'],['quakeSubway','subway'],['quakeTunnels','tunnels']])$('#'+id).onclick=()=>{setLayer(layer);close();};$('#randomTornadoes').onchange=()=>{const r=setRandomTornadoes(c,$('#randomTornadoes').checked);if(!r.ok)return notify(r.error);save();update();};$('#randomQuakes').onchange=()=>{const r=setRandomEarthquakes(c,$('#randomQuakes').checked);if(!r.ok)return notify(r.error);save();update();};$('#fireMap').onclick=()=>{setLayer('fire');close();};$('#fireRisk').onclick=()=>{setLayer('flammability');close();};$('#clearRubble').onclick=()=>{setTool('bulldoze');close();};$('#randomFires').onchange=()=>{const r=setRandomFires(c,$('#randomFires').checked);if(!r.ok)return notify(r.error);save();update();};$('#reviewEmergency').onclick=()=>review(6);
}
